const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto'),png=require('./png.cjs');const base='http://127.0.0.1:8765',name='眼睛 / 原版豆豆眼·定位',out=path.resolve('备份/20261031-豆豆眼同步人物分支-'+Date.now());
async function read(id){const r=await fetch(base+'/api/project?id='+encodeURIComponent(id));assert(r.ok);return {raw:await r.text(),etag:r.headers.get('etag')}}
(async()=>{fs.mkdirSync(out,{recursive:true});let source=await read('main'),main=JSON.parse(source.raw),sources=main.layers.filter(l=>l.name===name);assert.equal(sources.length,4);fs.writeFileSync(out+'/main-source.json',source.raw);let list=await(await fetch(base+'/api/projects')).json(),plans=[];for(let item of list.filter(x=>x.id.startsWith('character-'))){let before=await read(item.id),p=JSON.parse(before.raw),c=structuredClone(p),dir=path.join(out,item.id);fs.mkdirSync(dir);fs.writeFileSync(dir+'/before.json',before.raw);let added=0,frames=0;for(let src of sources){let ss=main.spriteSheets[src.sheetIndex],si=c.spriteSheets.findIndex(s=>s.name===ss.name);assert(si>=0,item.id+' missing '+ss.name);let ts=c.spriteSheets[si];assert.equal(ts.frameWidth,ss.frameWidth);assert.equal(ts.frameHeight,ss.frameHeight);let fd={};for(let [key,frame]of Object.entries(src.frameData)){let [,ai,fi]=key.split('_').map(Number),action=ss.actions[ai],tai=ts.actions.findIndex(a=>a.direction===action.direction&&a.name===action.name);assert(tai>=0&&ts.actions[tai].frames[fi]);let tk=`${si}_${tai}_${fi}`;assert.equal(frame.width,ts.actions[tai].frames[fi].width);let head=c.layers.find(l=>l.sheetIndex===si&&l.name==='head'&&l.frameData[tk]);assert(head,item.id+' '+tk);let d=png.decode(Buffer.from(frame.dataURL.split(',')[1],'base64')),h=png.decode(Buffer.from(head.frameData[tk].dataURL.split(',')[1],'base64'));for(let i=3;i<d.data.length;i+=4)if(d.data[i])assert(h.data[i],item.id+' '+tk+' eye outside head');fd[tk]=structuredClone(frame);frames++;}let existing=c.layers.find(l=>l.sheetIndex===si&&l.name===name);if(existing){assert.deepEqual(existing.frameData,fd,'Existing positioning eyes differ; inspect before overwriting');continue;}let active=c.layers.some(l=>l.sheetIndex===si&&!l.isGroup&&/眼/.test(l.name)&&l.visible);c.layers.push({...structuredClone(src),sheetIndex:si,parent:null,visible:!active,frameData:fd});added++;}
assert.deepEqual(c.layers.slice(0,p.layers.length),p.layers);let normalized=structuredClone(c);normalized.layers=p.layers;assert.deepEqual(normalized,p);fs.writeFileSync(dir+'/candidate.json',JSON.stringify(c));plans.push({id:item.id,name:item.name,etag:before.etag,sha256:crypto.createHash('sha256').update(before.raw).digest('hex'),added,frames,dir});console.log('CHECKED '+item.name+' '+frames+' cels; '+added+' layers');}
fs.writeFileSync(out+'/manifest.json',JSON.stringify(plans,null,2));fs.writeFileSync('自检记录/豆豆眼分支同步最新路径.txt',out);console.log('STAGED '+plans.length+' '+out);
})().catch(e=>{console.error(e);process.exitCode=1});
